package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.AllowAllScopesVO;

class AllowAllScopesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of allow all scopes of oauth client")
  void test_allow_all_scopes_value_holder_assign_plain_value() {
    Object holder = new Object();
    AllowAllScopesValueHolder<Object> value = new AllowAllScopesValueHolder<>(holder);
    Assertions.assertSame(holder, value.allowAllScopes(true), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowAllScopesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getAllowAllScopes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.allowAllScopesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowAllScopesValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of allow all scopes of oauth client")
  void test_allow_all_scopes_value_holder_assign_value_object() {
    Object holder = new Object();
    AllowAllScopesValueHolder<Object> value = new AllowAllScopesValueHolder<>(holder);
    AllowAllScopesVO vo = AllowAllScopesVO.from(true);
    Assertions.assertFalse(value.getAllowAllScopesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.allowAllScopes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAllowAllScopesValue().orElseThrow());
    Assertions.assertSame(holder, value.allowAllScopes(Optional.empty()));
    Assertions.assertFalse(value.getAllowAllScopesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.allowAllScopes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAllowAllScopesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of allow all scopes of oauth client against the original")
  void test_allow_all_scopes_value_holder_read() {
    Object holder = new Object();
    AllowAllScopesValueHolder<Object> value = new AllowAllScopesValueHolder<>(holder);
    AllowAllScopesVO vo = AllowAllScopesVO.from(true);
    AllowAllScopesVO other = AllowAllScopesVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getAllowAllScopesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAllowAllScopes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAllowAllScopes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.allowAllScopes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAllowAllScopes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAllowAllScopes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of allow all scopes of oauth client")
  void test_allow_all_scopes_value_holder_unset() {
    Object holder = new Object();
    AllowAllScopesValueHolder<Object> value = new AllowAllScopesValueHolder<>(holder);
    AllowAllScopesVO vo = AllowAllScopesVO.from(true);
    value.allowAllScopes(vo);
    Assertions.assertSame(holder, value.unsetAllowAllScopesIfMatches("allowAllScopes_other"));
    Assertions.assertTrue(value.getAllowAllScopesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAllowAllScopesIfMatches("allowAllScopes"));
    Assertions.assertFalse(value.getAllowAllScopesValue().isPresent(),
        "The field name must clear the value");
    value.allowAllScopes(vo);
    Assertions.assertSame(holder, value.unsetAllowAllScopes());
    Assertions.assertFalse(value.getAllowAllScopesValue().isPresent(),
        "Unset must clear the value");
  }
}
